import { test, expect } from '@playwright/test';

test.describe('Phone Number Field Numeric Input Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should accept only numeric input in phone number field', async ({ page }) => {
    // Locate phone number input using getByLabel
    const phoneInput = page.getByLabel('Phone Number');
    await expect(phoneInput).toBeVisible();

    // Verify input field is empty initially
    await expect(phoneInput).toHaveValue('');

    // Enter valid numeric input
    await phoneInput.fill('123496701');

    // Verify input contains only numbers
    await expect(phoneInput).toHaveValue('123496701');

    // Attempt to enter non-numeric characters
    await phoneInput.fill('1234-6790');

    // Verify input value is sanitized to only numbers
    await expect(phoneInput).toHaveValue('12346790');

    // Attempt to enter letters
    await phoneInput.fill('12345abc');

    // Verify input value is sanitized to only numbers
    await expect(phoneInput).toHaveValue('12345');

    // Verify error message does not appear for valid numeric input
    const errorMessage = page.getByText('Phone number must contain only digits');
    await expect(errorMessage).not.toBeVisible();

    // Submit the form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should display error message when phone number field is empty and required', async ({ page }) => {
    // Locate phone number input using getByLabel
    const phoneInput = page.getByLabel('Phone Number');
    await expect(phoneInput).toBeVisible();

    // Verify input field is empty
    await expect(phoneInput).toHaveValue('');

    // Attempt to submit the form without entering a phone number
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error message appears for empty field
    const errorMessage = page.getByText('Phone number is required');
    await expect(errorMessage).toBeVisible();

    // Verify phone input has validation styling (e.g., red border)
    await expect(phoneInput).toHaveAttribute('aria-invalid', 'true');

    // Verify form was not submitted
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();

    // Enter valid numeric input
    await phoneInput.fill('123456790');

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify phone input no longer has validation styling
    await expect(phoneInput).not.toHaveAttribute('aria-invalid', 'true');
  });
});
